                        //                 {
                        //                     "guid":
                        //                     "07efc37f-d1ec-4bc9-8339-a745256ea2ba",
                        //                     "is_deposit_enabled": true,
                        //                     "gateway_name": "Ethereum",
                        //                     "min_withdrawal_amount":
                        //                     "0.000001", "withdrawal_fee":
                        //                     "5.71", "is_withdrawal_enabled":
                        //                     true, "min_deposit_amount":
                        //                     "0.000001", "is_memo_required":
                        //                     false, "withdrawal_scale": 6,
                        //                     "scale": 12
                        //                 },
                        //                 {
                        //                     "guid":
                        //                     "4e387a9a-a480-40a3-b4ae-ed1773c2db5a",
                        //                     "is_deposit_enabled": true,
                        //                     "gateway_name":
                        //                     "BinanceSmartChain",
                        //                     "min_withdrawal_amount": "10",
                        //                     "withdrawal_fee": "5",
                        //                     "is_withdrawal_enabled": false,
                        //                     "min_deposit_amount": "1",
                        //                     "is_memo_required": false,
